<?php
require_once __DIR__.'/config/config.php';require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM ligler WHERE id=? AND aktif=1');$st->execute([$id]);$lig=$st->fetch();if(!$lig){header('Location: '.BASE_URL.'/ligler.php');exit;}$sayfa_baslik=$lig['lig_adi'];$aktif='ligler';require_once __DIR__.'/includes/header.php';$gs=$pdo->prepare('SELECT * FROM gruplar WHERE lig_id=? ORDER BY grup_adi');$gs->execute([$id]);$gruplar=$gs->fetchAll();$grupId=(int)($_GET['grup_id']??($gruplar[0]['id']??0));$bireysel_fikstur=[];
if($lig['tur']==='bireysel'){$st=$pdo->prepare('SELECT s.*,t.takim_adi FROM bireysel_lig_kayitlari k JOIN sporcular s ON s.id=k.sporcu_id LEFT JOIN takimlar t ON t.id=s.takim_id WHERE k.lig_id=? AND k.grup_id=? ORDER BY s.toplam_puan DESC,s.atis_sayisi ASC');$st->execute([$id,$grupId]);$liste=$st->fetchAll();$fs=$pdo->prepare('SELECT * FROM bireysel_fikstur WHERE lig_id=? AND grup_id=? ORDER BY tarih,saat');$fs->execute([$id,$grupId]);$bireysel_fikstur=$fs->fetchAll();}else{$st=$pdo->prepare('SELECT * FROM takimlar WHERE grup_id=? ORDER BY toplam_set DESC,toplam_puan DESC');$st->execute([$grupId]);$liste=$st->fetchAll();}
?><main class="main-content"><section class="page-heading"><span><?= $lig['tur']==='bireysel'?'Bireysel Lig':'Takım Ligi' ?></span><h1><?= e($lig['lig_adi']) ?></h1><p><?= e($lig['aciklama']) ?></p></section><section class="card"><form method="get"><input type="hidden" name="id" value="<?= $id ?>"><label>Grup seçin<select class="group-select" name="grup_id" onchange="this.form.submit()"><?php foreach($gruplar as $g):?><option value="<?= (int)$g['id'] ?>" <?= $grupId===(int)$g['id']?'selected':'' ?>><?= e($g['grup_adi']) ?></option><?php endforeach;?></select></label></form><?php if($lig['tur']==='bireysel' && $bireysel_fikstur):?><h2>Bireysel Lig Fikstürü</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Tarih</th><th>Saat</th><th>Yer</th><th>Açıklama</th></tr></thead><tbody><?php foreach($bireysel_fikstur as $f):?><tr><td><?= tr_tarih($f['tarih']) ?></td><td><?= tr_saat($f['saat']) ?></td><td><?= e($f['yer']) ?></td><td><?= e($f['aciklama']?:'—') ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><div class="table-wrap"><table class="data-table"><thead><?php if($lig['tur']==='bireysel'):?><tr><th>#</th><th>Sporcu</th><th>Takım</th><th>Puan</th></tr><?php else:?><tr><th>#</th><th>Takım</th><th>O</th><th>G</th><th>Set</th><th>Puan</th></tr><?php endif;?></thead><tbody><?php foreach($liste as $i=>$x):if($lig['tur']==='bireysel'):?><tr><td><?= $i+1 ?></td><td><a href="<?= BASE_URL ?>/sporcu.php?id=<?= (int)$x['id'] ?>"><?= e($x['ad'].' '.$x['soyad']) ?></a></td><td><?= e($x['takim_adi']?:'—') ?></td><td><?= (int)$x['toplam_puan'] ?></td></tr><?php else:?><tr><td><?= $i+1 ?></td><td><a href="<?= BASE_URL ?>/takim.php?id=<?= (int)$x['id'] ?>"><?= e($x['takim_adi']) ?></a></td><td><?= (int)$x['oynanan_mac'] ?></td><td><?= (int)$x['kazanilan_mac'] ?></td><td><?= (int)$x['toplam_set'] ?></td><td><?= (int)$x['toplam_puan'] ?></td></tr><?php endif;endforeach;?></tbody></table></div></section></main><?php require_once __DIR__.'/includes/sidebar.php';require_once __DIR__.'/includes/footer.php'; ?>
